 38→    int global_tid = blockIdx.x * BLOCK + threadIdx.x;
 39→    int group_idx = global_tid / LANES;
 40→    int lane = global_tid % LANES;
 41→
 42→    if (group_idx >= total_groups) return;
 43→
 44→    int row = group_idx / num_groups_per_row;
 45→    int grp = group_idx % num_groups_per_row;
 46→
 47→    int base = row * K + grp * GROUP_SIZE;
 48→    float v0 = __bfloat162float(A[base + lane * 2]);
 49→    float v1 = __bfloat162float(A[base + lane * 2 + 1]);
 50→
 51→    // Max abs reduction via shared memory
 52→    __shared__ float red[BLOCK];
 53→    int local_group = threadIdx.x / LANES;
 54→    float local_max = fmaxf(fabsf(v0), fabsf(v1));
 55→    red[threadIdx.x] = local_max;
 56→    __syncthreads();
 57→
 58→    int group_base = local_group * LANES;
 59→    for (int stride = LANES / 2; stride > 0; stride >>= 1) {
 60→        if (lane < stride)
 61→            red[group_base + lane] = fmaxf(red[group_base + lane],
 62→                                            red[group_base + lane + stride]);
 63→        __syncthreads();
 64→    }
 65→    float group_max = red[group_base];
 66→    __syncthreads();
 67→
 68→    // E8M0 scale: floor(log2(amax / 6.0)) + 128
 69→    unsigned char scale_byte;
 70→    float scale_factor;
 71→
 72→    if (group_max > 0.0f) {
 73→        float log2_val = floorf(log2f(group_max / 6.0f)) + 128.0f;
 74→        log2_val = fminf(fmaxf(log2_val, 0.0f), 254.0f);
 75→        scale_byte = (unsigned char)log2_val;
 76→        scale_factor = exp2f((float)scale_byte - 127.0f);
 77→    } else {
 78→        scale_byte = 0;
 79→        scale_factor = 0.0f;
 80→    }
 81→
 82→    // Normalize to fp4 range [-6, 6]
 83→    float n0 = (scale_factor > 0.0f) ? v0 / scale_factor : 0.0f;
 84→    float n1 = (scale_factor > 0.0f) ? v1 / scale_factor : 0.0f;
 85→
 86→    // fp4 e2m1 encoding (nearest rounding)
 87→    auto encode_fp4 = [](float x) -> unsigned char {
 88→        int sign = (x < 0.0f) ? 1 : 0;
 89→        float ax = fabsf(x);
 90→        int mag;
 91→        if      (ax < 0.25f) mag = 0;
 92→        else if (ax < 0.75f) mag = 1;
 93→        else if (ax < 1.25f) mag = 2;
 94→        else if (ax < 1.75f) mag = 3;
 95→        else if (ax < 2.5f)  mag = 4;
 96→        else if (ax < 3.5f)  mag = 5;
 97→        else if (ax < 5.0f)  mag = 6;
 98→        else                  mag = 7;
 99→        return (unsigned char)((sign << 3) | mag);
100→    };
101→
102→    unsigned char fp4_0 = encode_fp4(n0);
103→    unsigned char fp4_1 = encode_fp4(n1);
104→
105→    // Pack fp4x2: low nibble = element 0, high nibble = element 1
106→    unsigned char packed = (fp4_1 << 4) | (fp4_0 & 0x0F);
107→
108→    int out_idx = row * (K / 2) + grp * (GROUP_SIZE / 2) + lane;
109→    A_q[out_idx] = packed;
110→
111→    if (lane == 0) {
