116→std::vector<torch::Tensor> mxfp4_quant(torch::Tensor A) {
117→    int M = A.size(0);
118→    int K = A.size(1);
119→
120→    auto A_q = torch::empty({M, K / 2}, torch::dtype(torch::kUInt8).device(A.device()));
121→    auto A_scale = torch::empty({M, K / 32}, torch::dtype(torch::kUInt8).device(A.device()));
122→
123→    int num_groups = M * (K / GROUP_SIZE);
124→    int threads_needed = num_groups * 16;
125→    int blocks = (threads_needed + BLOCK - 1) / BLOCK;
126→
127→    hipLaunchKernelGGL(mxfp4_quant_kernel,
128→        dim3(blocks), dim3(BLOCK), 0, 0,
129→        (const __hip_bfloat16*)A.data_ptr(),
130→        (unsigned char*)A_q.data_ptr(),
131→        (unsigned char*)A_scale.data_ptr(),
132→        M, K);
133→
134→    return {A_q, A_scale};
135→}
