159→            ],
160→            extra_include_paths=['/opt/rocm/include'],
161→            extra_ldflags=['-L/opt/rocm/lib', '-lamdhip64'],
162→            verbose=False,
163→        )
164→    except Exception:
165→        _ext_mod = None
166→    return _ext_mod
