171→    return x_fp4.view(dtypes.fp4x2), e8m0_shuffle(bs_e8m0).view(dtypes.fp8_e8m0)
172→
173→
174→def custom_kernel(data: input_t) -> output_t:
175→    A, B, B_q, B_shuffle, B_scale_sh = data
176→    M, K = A.shape
177→
178→    ext = _ensure_ext()
179→    if ext is not None:
180→        try:
181→            A_q, A_scale_raw = ext.mxfp4_quant(A.contiguous())
182→            A_q_fp4x2 = A_q.view(dtypes.fp4x2)
183→            A_scale_sh = e8m0_shuffle(A_scale_raw).view(dtypes.fp8_e8m0)
184→            return aiter.gemm_a4w4(
185→                A_q_fp4x2, B_shuffle, A_scale_sh, B_scale_sh,
186→                dtype=dtypes.bf16, bpreshuffle=True,
187→            )
188→        except Exception:
189→            pass
190→
191→    # Fallback to original pipeline
192→    A_q_fb, A_scale_fb = _fallback_quant(A)
193→    return aiter.gemm_a4w4(
194→        A_q_fb, B_shuffle, A_scale_fb, B_scale_sh,
195→        dtype=dtypes.bf16, bpreshuffle=True,
